package com.qinghe.life.vo;
import com.qinghe.life.entity.Goods; import com.qinghe.life.entity.GoodsCategory; import java.math.BigDecimal; import lombok.*;
@Data @NoArgsConstructor @AllArgsConstructor public class AdminGoodsVO { private Long id; private Long shopId; private String shopName; private Long shopCategoryId; private Long categoryId; private String categoryName; private String name; private String description; private BigDecimal price; private Integer stock; private Integer salesCount; private String saleStatus; private String coverImage; public static AdminGoodsVO from(Goods g,String shopName,Long shopCategoryId,GoodsCategory category){return new AdminGoodsVO(g.getId(),g.getShopId(),shopName,shopCategoryId,g.getCategoryId(),category == null ? null : category.getName(),g.getName(),g.getDescription(),g.getPrice(),g.getStock(),g.getSalesCount(),g.getSaleStatus(),g.getCoverImage());}}
